cd /testbed && python3 - <<'PY'
import difflib
import subprocess
fixtures = {
    'FieldDefaultsViaConfigOnRecord': (
        '//CONF: lombok.fieldDefaults.defaultPrivate = true\n//CONF: lombok.fieldDefaults.defaultFinal = true\n',
        'public record FieldDefaultsViaConfigOnRecord(String value) {\n\tstatic int counter;\n\n\tpublic record Empty() {\n\t}\n}\n',
        '''public record FieldDefaultsViaConfigOnRecord(String value) {
  public static record Empty() {
    public Empty() {
      super();
    }
  }
/* Implicit */  private final String value;
  static int counter;
  public FieldDefaultsViaConfigOnRecord(String value) {
    super();
    .value = value;
  }
  <clinit>() {
  }
}
'''),
    'FieldDefaultsViaConfigPrivateOnRecord': (
        '//CONF: lombok.fieldDefaults.defaultPrivate = true\n',
        'public record FieldDefaultsViaConfigPrivateOnRecord() {\n\tstatic int counter;\n}\n',
        '''public record FieldDefaultsViaConfigPrivateOnRecord() {
  static int counter;
  public FieldDefaultsViaConfigPrivateOnRecord() {
    super();
  }
  <clinit>() {
  }
}
'''),
    'FieldDefaultsViaConfigFinalOnRecord': (
        '//CONF: lombok.fieldDefaults.defaultFinal = true\n',
        'public record FieldDefaultsViaConfigFinalOnRecord(String value) {\n}\n',
        '''public record FieldDefaultsViaConfigFinalOnRecord(String value) {
/* Implicit */  private final String value;
  public FieldDefaultsViaConfigFinalOnRecord(String value) {
    super();
    .value = value;
  }
}
''')
}
patch = []
for name, (config, source, ecj) in fixtures.items():
    for directory, content in [('before', config + '\n' + source), ('after-delombok', source), ('after-ecj', ecj)]:
        path = 'test/transform/resource/' + directory + '/' + name + '.java'
        content = '// version 14:\n// unchanged\n' + content
        patch.extend(difflib.unified_diff([], content.splitlines(True), fromfile='/dev/null', tofile='b/' + path))
subprocess.run(['git', 'apply'], input=''.join(patch), text=True, check=True)
PY
ant test.javacCurrent > build/fielddefaults-regression-baseline.log 2>&1; result=$?; grep -nE 'FieldDefaultsViaConfig.*Record|FieldDefaults is only supported|\[FAIL\]|Total time' build/fielddefaults-regression-baseline.log | tail -45; exit "$result"

